/*references*/
/*
●book of shaders
https://thebookofshaders.com/

●kishimisu チュートリアル
https://www.youtube.com/watch?v=f4s1h2YETNY

●Ginさんチュートリアル
https://gin-graphic.hatenablog.com/entry/2020/12/01/174242
*/



let vs = `
  precision highp float;

  attribute vec3 aPosition;

  void main() {
     vec4 positionVec4 = vec4(aPosition, 1.0);

     gl_Position = positionVec4;
}
`;

let fs = `
  precision highp float;
  uniform vec2  u_resolution;
  uniform float u_time;
  #define PI 3.14159265359
  #define TWO_PI 6.28318530718

vec3 palette(float t){
	vec3 a = vec3(0.5, 0.5, 0.5);
	vec3 b = vec3(0.5, 0.5, 0.5);
	vec3 c = vec3(1.0, 1.0, 1.0);
	vec3 d = vec3(0.00, 0.10, 0.20);

    return a + b*cos(6.28318*(c*t+d)); 
}

vec2 rotate2D(vec2 _st,float _angle){
_st -= 0.5;
_st = mat2(cos(_angle),-sin(_angle),sin(_angle),cos(_angle))*_st;
_st += 0.5;

return _st;
}

vec2 tile(vec2 _st, float _zoom){
_st *= _zoom;
return fract(_st);
}

vec2 rotateTilePattern(vec2 _st){

    //  Scale the coordinate system by 2x2
    _st *= 3.0;

    //  Give each cell an index number
    //  according to its position
    float index = 0.0;
    index += step(1., mod(_st.x,2.0));
    index += step(1., mod(_st.y,2.0))*2.0;

    //      |
    //  2   |   3
    //      |
    //--------------
    //      |
    //  0   |   1
    //      |

    // Make each cell between 0.0 - 1.0
    _st = fract(_st);

    // Rotate each cell according to the index
    if(index == 1.0){
        //  Rotate cell 1 by 90 degrees
        _st = rotate2D(_st,PI*1.5);
    } else if(index == 2.0){
        //  Rotate cell 2 by -90 degrees
        _st = rotate2D(_st,PI*-1.5);
    } else if(index == 3.0){
        //  Rotate cell 3 by 180 degrees
        _st = rotate2D(_st,PI);
    }

    return _st;
}

void main(){
  vec2 st = (gl_FragCoord.xy*2.0 - u_resolution.xy)/u_resolution.y;
  vec3 color = vec3(0.0);
  float d = 0.0;
  vec2 uv0 = st;

  // Remap the space to -1. to 1.
    st = tile(st,2.0);
    st = rotateTilePattern(st);

  // Number of sides of your shape
  int N = 1;

  // Angle and radius from the current pixel
  float a = atan(st.x,st.y)+PI;
  float r = TWO_PI/float(N);

  // Shaping function that modulate the distance
  d = cos(floor(.2+a/r)*r)*length(st);

float num =2.0;//100くらいもいい。
  d =fract(d*num+u_time)/num;
  d = smoothstep(0.0,0.1,d);
d = abs(d);
d= 0.1/d;


	color = palette(length(st*uv0)+u_time*0.8);
	color *= d;

  gl_FragColor = vec4(color,1.0);
}
`;


let theShader;

let t = 0.0;
let vel = 0.01;

function setup() {
	let w = 800;
	createCanvas(w, w, WEBGL);
	theShader = createShader(vs, fs);
}

function draw() {
	shader(theShader);
	theShader.setUniform('u_time', t);
	theShader.setUniform('u_resolution', [width, height]);
	theShader.setUniform('u_mouse', [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))]);
	quad(-1, -1, -1, 1, 1, 1, 1, -1);
	resetShader();
	t += vel;
}

